#include <stdio.h>
/* flow-graph nodes marked as N1..N9 */
int f(int n) {
    int s = 0;                 /* N1 */
    while (n > 0) {            /* N2  predicate 1 */
        if (n % 2 == 0)        /* N3  predicate 2 */
            s += n;            /* N4 */
        else
            s -= 1;            /* N5 */
        n--;                   /* N6 */
    }
    if (s > 10)                /* N7  predicate 3 */
        s = 10;                /* N8 */
    return s;                  /* N9 */
}
int main(void) {
    printf("%d %d %d\n", f(3), f(4), f(8));
    return 0;
}
